INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1359042, 172292, 34283, '<td valign="top">Intriguing....</td>', 'Intriguing....', '2005-05-04 10:37:56.000000', NULL, 1),
(1359043, 173257, 32196, '<td valign="top">i like it very much!! colours, sharpness, and the reflections. maybe that one place is a bit overexposed.. hmm.. 9</td>', 'i like it very much!! colours, sharpness, and the reflections. maybe that one place is a bit overexposed.. hmm.. 9', '2005-05-04 10:37:57.000000', NULL, 1),
(1359045, 173669, 25189, '<td valign="top">another stop or two of exposure would help greatly here.  Also, the white balance is just far enough off to be annoying.  Either go all the way for firey orage or back closer to true white but avoid this middle ground.  Also, get your subjects to stay still unless you really want them all blurry and distracting.</td>', 'another stop or two of exposure would help greatly here.  Also, the white balance is just far enough off to be annoying.  Either go all the way for firey orage or back closer to true white but avoid this middle ground.  Also, get your subjects to stay still unless you really want them all blurry and distracting.', '2005-05-04 10:38:15.000000', NULL, 1),
(1359046, 173442, 2560, '<td valign="top">Being a night shot doesn''t add anything to this photo.</td>', 'Being a night shot doesn''t add anything to this photo.', '2005-05-04 10:38:26.000000', NULL, 1),
(1359048, 172518, 32196, '<td valign="top">i wish it was sharper.. 6</td>', 'i wish it was sharper.. 6', '2005-05-04 10:38:29.000000', NULL, 1),
(1359049, 173219, 34283, '<td valign="top">Very good, but a crop at the bottom would make it nicer.</td>', 'Very good, but a crop at the bottom would make it nicer.', '2005-05-04 10:38:32.000000', NULL, 1),
(1359052, 173502, 25189, '<td valign="top">good work on the white balance.  The photo is well done from a technical standpoint, but the composition doesn''t really do much for me with the parking lot and lights in the foreground.</td>', 'good work on the white balance.  The photo is well done from a technical standpoint, but the composition doesn''t really do much for me with the parking lot and lights in the foreground.', '2005-05-04 10:39:25.000000', NULL, 1),
(1359056, 171713, 34283, '<td valign="top">This is just incredible....</td>', 'This is just incredible....', '2005-05-04 10:39:50.000000', NULL, 1),
(1359057, 173794, 25189, '<td valign="top">expose more!</td>', 'expose more!', '2005-05-04 10:40:04.000000', NULL, 1),
(1359058, 173714, 2560, '<td valign="top">I think you needed a better subject to put in the forground.</td>', 'I think you needed a better subject to put in the forground.', '2005-05-04 10:40:12.000000', NULL, 1),
(1359060, 172385, 25189, '<td valign="top">nice job.  the jiggle factor with the lights here is about perfect for my tastes.  I''m guessing the camera was on a tripod attached to the trunk and you are triggering it with a handheld remote?  The one thing that bothers me is how the hotshoe flash is to the side of the shot, creating a huge shadow on the left of the subjects.  I shouldn''t complain since you apparently were willing to risk your equipment on the back of your car, but if there was some way to make the lighting more even from side to side (even just getting the flash above or below the lens instead of to the side) would probably make the picture even better.  9 from me</td>', 'nice job.  the jiggle factor with the lights here is about perfect for my tastes.  I''m guessing the camera was on a tripod attached to the trunk and you are triggering it with a handheld remote?  The one thing that bothers me is how the hotshoe flash is to the side of the shot, creating a huge shadow on the left of the subjects.  I shouldn''t complain since you apparently were willing to risk your equipment on the back of your car, but if there was some way to make the lighting more even from side to side (even just getting the flash above or below the lens instead of to the side) would probably make the picture even better.  9 from me', '2005-05-04 10:43:09.000000', NULL, 1),
(1359062, 173439, 34283, '<td valign="top">Brilliant!</td>', 'Brilliant!', '2005-05-04 10:43:49.000000', NULL, 1),
(1359064, 173436, 25189, '<td valign="top">this effect works better against a jet black background.  Nice photo nonetheless.  I''m betting it''s a self portrait.</td>', 'this effect works better against a jet black background.  Nice photo nonetheless.  I''m betting it''s a self portrait.', '2005-05-04 10:44:01.000000', NULL, 1),
(1359065, 172292, 25189, '<td valign="top">too underexposed</td>', 'too underexposed', '2005-05-04 10:44:15.000000', NULL, 1),
(1359066, 173648, 34283, '<td valign="top">I love the shades of blue and gray.</td>', 'I love the shades of blue and gray.', '2005-05-04 10:44:21.000000', NULL, 1),
(1359067, 173564, 35548, '<td valign="top">Okay, I think I found another winner. 10  I like the weight of this image, I like the overall color. I think the photographer did a great job on all fronts.</td>', 'Okay, I think I found another winner. 10  I like the weight of this image, I like the overall color. I think the photographer did a great job on all fronts.', '2005-05-04 10:44:22.000000', NULL, 1),
(1359069, 173436, 17486, '<td valign="top">Great idea.  I like the effect, but I think the photo would be stonger if flash unit was not visiable.</td>', 'Great idea.  I like the effect, but I think the photo would be stonger if flash unit was not visiable.', '2005-05-04 10:44:39.000000', NULL, 1),
(1359071, 173786, 25189, '<td valign="top">nice subject matter, but get the white balance fixed!  Deep reddish-orange-lit photos really only work well when there is fire involved.</td>', 'nice subject matter, but get the white balance fixed!  Deep reddish-orange-lit photos really only work well when there is fire involved.', '2005-05-04 10:45:19.000000', NULL, 1),
