INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1359729, 173374, 31211, '<td valign="top">I really like your image - very good quality, good composition and fantastic colors. I think its very well executed and overall its a splendid image (sky and reflections are beautiful). The only thing that bothers me here (just a little bit) is the fact that the background lights and the boat to the right seem to be out of focus (or very soft). Anyway, 9.</td>', 'I really like your image - very good quality, good composition and fantastic colors. I think its very well executed and overall its a splendid image (sky and reflections are beautiful). The only thing that bothers me here (just a little bit) is the fact that the background lights and the boat to the right seem to be out of focus (or very soft). Anyway, 9.', '2005-05-04 13:09:15.000000', NULL, 1),
(1359731, 173897, 24454, '<td valign="top">I really like this!   It has kind of an art deco kind of poster fel to it.   You did great with the sharpness.</td>', 'I really like this!   It has kind of an art deco kind of poster fel to it.   You did great with the sharpness.', '2005-05-04 13:09:43.000000', NULL, 1),
(1359732, 173725, 31637, '<td valign="top">cool, but your light post lamps are too overexposed</td>', 'cool, but your light post lamps are too overexposed', '2005-05-04 13:09:55.000000', NULL, 1),
(1359733, 172182, 31637, '<td valign="top">do you mean twilight?  4</td>', 'do you mean twilight?  4', '2005-05-04 13:10:12.000000', NULL, 1),
(1359734, 173743, 31637, '<td valign="top">way to dark and underexposed</td>', 'way to dark and underexposed', '2005-05-04 13:10:31.000000', NULL, 1),
(1359735, 173852, 31637, '<td valign="top">too confusing</td>', 'too confusing', '2005-05-04 13:11:07.000000', NULL, 1),
