(1359803, 173436, 8522, '<td valign="top">Colour balance is too orange. Source of light (your flash) is a bit too obvious for me here.</td>', 'Colour balance is too orange. Source of light (your flash) is a bit too obvious for me here.', '2005-05-04 13:26:19.000000', NULL, 1),
(1359804, 171539, 29148, '<td valign="top">Too dark for my taste</td>', 'Too dark for my taste', '2005-05-04 13:26:21.000000', NULL, 1),
