(1360060, 171945, 24212, '<td valign="top">I like the way that the roofline and kerbline converge towards the left of the frame.</td>', 'I like the way that the roofline and kerbline converge towards the left of the frame.', '2005-05-04 14:53:24.000000', NULL, 1),
(1360061, 173712, 37302, '<td valign="top">this looks like it is shot at dusk -- not as late night as I would expect for this challenge<br/>crystaljae.blogspot.com</td>', 'this looks like it is shot at dusk -- not as late night as I would expect for this challengecrystaljae.blogspot.com', '2005-05-04 14:54:06.000000', NULL, 1),
(1360062, 173339, 24212, '<td valign="top">Great composition. Nicely sharp. I just wish that the tops of the spires were a little brighter.</td>', 'Great composition. Nicely sharp. I just wish that the tops of the spires were a little brighter.', '2005-05-04 14:54:19.000000', NULL, 1),
