INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1361195, 173852, 31133, '<td valign="top">This is a picture with a whole story! There''s so much going on here and you''ve still managed to keep it from looking over-cluttered. Nice work. The only thing that might make it better (for my taste only) is if the bright white light at the bottom, with its long streak, wasn''t quite so bright.</td>', 'This is a picture with a whole story! There''s so much going on here and you''ve still managed to keep it from looking over-cluttered. Nice work. The only thing that might make it better (for my taste only) is if the bright white light at the bottom, with its long streak, wasn''t quite so bright.', '2005-05-04 20:08:55.000000', NULL, 1),
