(1362059, 172841, 28276, '<td valign="top">as many of these car light trails as i''ve seen, i just really like this one...</td>', 'as many of these car light trails as i''ve seen, i just really like this one...', '2005-05-05 01:20:19.000000', NULL, 1),
(1362063, 173339, 36762, '<td valign="top">I really like the shot. Maybe crop the picture more around the building.</td>', 'I really like the shot. Maybe crop the picture more around the building.', '2005-05-05 01:20:56.000000', NULL, 1),
(1362070, 173728, 34390, '<td valign="top">The cart stands out well against the black.</td>', 'The cart stands out well against the black.', '2005-05-05 01:22:02.000000', NULL, 1),
(1362071, 173155, 34390, '<td valign="top">You''ve captured some beautiful reflections.</td>', 'You''ve captured some beautiful reflections.', '2005-05-05 01:22:32.000000', NULL, 1),
