(1362218, 172318, 29474, '<td valign="top">Too bright for me. A bit over-exposed?</td>', 'Too bright for me. A bit over-exposed?', '2005-05-05 02:29:17.000000', NULL, 1),
(1362219, 172809, 37302, '<td valign="top">very nice abstract. love it</td>', 'very nice abstract. love it', '2005-05-05 02:29:51.000000', NULL, 1),
