(1362227, 171923, 35764, '<td valign="top">i like the silhouette and framing</td>', 'i like the silhouette and framing', '2005-05-05 02:31:05.000000', NULL, 1),
(1362228, 173714, 37053, '<td valign="top">Fun shot.<br/><br/><i>Message edited by author 2006-08-28 12:47:14.</i></td>', 'Fun shot.', '2005-05-05 02:31:06.000000', '2006-08-28 13:47:14.000000', 1),
