(1372566, 173021, 36528, '<td valign="top">The camera has moved during exposure???</td>', 'The camera has moved during exposure???', '2005-05-09 03:26:10.000000', NULL, 1),
(1372570, 173869, 36528, '<td valign="top">Nice picture and interesting colours. Controlling the blowout on the house would have ensured a better score I feel.</td>', 'Nice picture and interesting colours. Controlling the blowout on the house would have ensured a better score I feel.', '2005-05-09 03:28:28.000000', NULL, 1),
