(1377239, 172519, 23458, '<td valign="top">Yep, I really not to degrade, but this clearly should have scored higher than all three ribbon winners.</td>', 'Yep, I really not to degrade, but this clearly should have scored higher than all three ribbon winners.', '2005-05-11 02:41:44.000000', NULL, 0),
(1377242, 172610, 25946, '<td valign="top">Great image and congratulations.</td>', 'Great image and congratulations.', '2005-05-11 02:42:47.000000', NULL, 0),
